{
  "darija_arabic": "أ مي، غدا عيد ميلادي. واش غادي تعيطي ليا؟",
  "darija_latin": "a mi, ghadda 3id miladi. wash ghadi t3ayti liya?",
  "feeling": ["neutral"]
}

{
  "darija_arabic": "أ جدي، غادي نجي للمغرب فالعيد مع ماما وبابا.",
  "darija_latin": "a jeddi, ghadi nji lmeghrib f l3id m3a mama w baba.",
  "feeling": ["neutral"]
}

{
  "darija_arabic": "أ مي، شديت البيرمي من أول مرة! راني فرحانة بزاف.",
  "darija_latin": "a mi, cheddit lbirmi mn awal marra! rani fer7ana bzaf.",
  "feeling": ["pride"]
}

{
  "darija_arabic": "أ مي، الكولي وصل، بارك الله فيك. كانو فيه الحلوة وزيت الزيتون.",
  "darija_latin": "a mi, lcoli wsel, barak allah fik. kanou fih l7alwa w zit zzitoun.",
  "feeling": ["neutral"]
}

{
  "darija_arabic": "أ مي، كنبغيك. نتي أقوى وحدة كنعرف.",
  "darija_latin": "a mi, kanbghik. nti aqwa wehda kan3ref.",
  "feeling": ["love", "pride"]
}

{
  "darija_arabic": "أ مي، التيليفون ديالي كان مهرّس، هاديك علاش ما كنتش كنرد عليك.",
  "darija_latin": "a mi, ttéléphone dyali kan mherres, hadik 3lach ma kentch kenred 3lik.",
  "feeling": ["neutral"]
}

{
  "darija_arabic": "أ حنيني، عيدك مبارك! يا ريتني كنت معاكي.",
  "darija_latin": "a 7nini, 3idk mabrouk! ya ritni kent m3aki.",
  "feeling": ["love", "longing"]
}
